"""Rebuild the offline concept index and metadata; does not change game data."""
import json, hashlib, html, shutil
from pathlib import Path
from PIL import Image
ROOT=Path(__file__).resolve().parents[3]
DOC=Path(__file__).resolve().parent
ART=ROOT/'art/creatures/rabbito-family-v1'
specs=[
 ('rastro-dos-ventos','Rastro dos Ventos','rastro',3,'Velocista','Redirecionar o próprio salto','Coelho juvenil esguio; pernas traseiras sanfonadas e orelhas-leme recuadas.','Aprende a escolher a aterrissagem em vez de apenas saltar.','Dobras de mola nas pernas; orelhas alteram a trajetória.','A linha delicada limita confrontos prolongados e aterrissagens sem espaço.'),
 ('arauto-da-tempestade','Arauto da Tempestade','arauto',4,'Velocista','Abrir passagem','Lebre adulta quadrúpede, peito profundo e orelhas-velas em V.','A velocidade antes individual passa a abrir uma rota para os outros.','Base de quatro apoios e grandes velas auriculares recebem e desviam vento.','Exige espaço para manobrar; sustentar uma posição não é sua especialidade.'),
 ('mestre-dos-fios','Mestre dos Fios','mestre',3,'Condutor','Medir a tensão','Coelho juvenil ereto; orelhas molduram um losango aberto e patas seguram a linha.','Troca a pressa pelo cuidado com os limites do Elo.','Patas curtas ajustam o mesmo fio; orelhas oferecem pontos de tensão.','Voo lento e preparação tornam reposicionamento imediato mais difícil.'),
 ('tecelao-da-aurora','Tecelão da Aurora','tecelão',4,'Condutor','Sustentar uma travessia','Coelho adulto largo, baixo e quadrúpede; velas auriculares abertas como um tear vivo.','Aprende a sustentar uma ligação para além do próprio conforto.','Torso de pipa-caixa e apoios afastados distribuem a tensão da rabiola.','Precisa de estabilidade; manter uma ligação compromete sua mobilidade.'),
 ('rabbitknight','Rabbitknight','knight',None,'Especial','Aparar e responder','Coelho boxeador compacto; luvas de papel dobrado e máscara bucal.','Alternativa de disciplina corporal sem continuação evolutiva registrada.','Luvas vivas absorvem impacto; orelhas fecham a guarda.','Alcance curto e guarda fechada limitam controle distante.')
]
prompts=json.loads((DOC/'generation-inputs.json').read_text(encoding='utf-8'))['prompts']
sources={s['id']:s for s in json.loads((DOC/'generation-sources.json').read_text(encoding='utf-8'))}
nodes=[dict(id='rabbito',name='Rabbito',kind='stage',stage=2,identity='Creme, turquesa e dourado; duas orelhas-pipa, rabiola de fio com três laços.',story='Criado e montado por Kael; a Rabiola Antiga dá vida à sua criação singular.',decision_status='approved',approval_note='Identidade existente preservada de art/soulgen/keys/rabbito/color-rig-v2 e origem na Bíblia. A associação ao grau II é apenas hipótese documental.',production_status='concept',implementation='existente; não alterada',art='../../../art/soulgen/keys/rabbito/color-rig-v2/concept.png',brief='../evolucoes-v1/briefs/rabbito.md',route='Base',action='Pular',tradeoff='Não reescrito neste teste.',maturity='Grau II sugerido; não é cânone de estágios.')]
for ident,name,key,stage,route,verb,anatomy,story,mechanism,cost in specs:
 p=ART/ident/'concept-v1';p.mkdir(parents=True,exist_ok=True)
 brief=f'''# {name}\n\nEstado: proposta visual, sem integração. Nome registrado nas classes web; sua tradução em forma e maturidade ainda não foi aprovada.\n\n## Definido\nRabbito é criação singular de Kael, animada pela Rabiola Antiga. A classe {route} e seus rótulos vêm de src/engine.js. Rabbitknight usa luvas e máscara bucal e não tem sequência registrada.\n\n## Observado\nCreme/turquesa/dourado; rosto de coelho, orelhas de pipa, dobras e vareta. Rabiola de fio com três laços.\n\n## Proposta\nAnatomia: {anatomy}\nMaturidade: {stage if stage else 'configuração sem estágio definido'}. Verbo: {verb}.\nHistória interpretativa: {story}\nConstrução que executa a ação: {mechanism}\nLimitação proposta: {cost}\n\n## Desconhecido\nCondições, custos, níveis, material e disponibilidade; nomes de espécie separados das classes; associação definitiva III/IV. Nenhuma nova cena obrigatória. Não há infância selvagem anterior à criação por Kael.\n'''
 (p/'brief.md').write_text(brief,encoding='utf-8')
 (p/'prompt.txt').write_text(prompts[key],encoding='utf-8')
 image=p/'concept.png'
 if image.exists():
  im=Image.open(image)
  manifest=dict(id=ident,tool='image_gen.imagegen',source=sources.get(ident,{}).get('source','não registrado'),sha256=hashlib.sha256(image.read_bytes()).hexdigest(),width=im.width,height=im.height,mode=im.mode,alpha='A' in im.getbands(),references=[dict(path='art/soulgen/keys/rabbito/color-rig-v2/concept.png',role='Identidade autoral e acabamento')],prompt='prompt.txt',decision_status='proposed',production_status='concept',implementation='não integrado',technical_pixel_art=False)
  if ident=='arauto-da-tempestade':manifest['references'].append(dict(path='art/creatures/rabbito-family-v1/rastro-dos-ventos/concept-v1/concept.png',role='Continuidade do piloto juvenil'))
  if ident=='tecelao-da-aurora':
   manifest['references'].append(dict(path='art/creatures/rabbito-family-v1/mestre-dos-fios/concept-v1/concept.png',role='Continuidade da rota condutora na geração inicial'))
   manifest['correction']=dict(prompt='prompt-correcao.txt',input='tentativa-01.png',reason='Remover leitura de punhos sobre pés adicionais')
  (p/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
 nodes.append(dict(id=ident,name=name,kind='configuration' if stage is None else 'stage',stage=stage,identity=anatomy,story=story,decision_status='proposed',production_status='concept' if image.exists() else 'brief',implementation='não integrado',art=f'../../../art/creatures/rabbito-family-v1/{ident}/concept-v1/concept.png' if image.exists() else None,brief=f'../../../art/creatures/rabbito-family-v1/{ident}/concept-v1/brief.md',route=route,action=verb,mechanism=mechanism,tradeoff=cost,maturity='Hipótese de associação III/IV; sem retcon de origem.'))
edges=[]
for origin,target,route,reason in [('rabbito','rastro-dos-ventos','Velocista','Precisão na aterrissagem reorganiza as pernas e as orelhas.'),('rastro-dos-ventos','arauto-da-tempestade','Velocista','Estabilidade adulta transforma impulso em abertura de rota.'),('rabbito','mestre-dos-fios','Condutor','Cuidado com a tensão reorganiza postura e pontos de apoio.'),('mestre-dos-fios','tecelao-da-aurora','Condutor','Distribuir carga permite sustentar ligações por mais tempo.'),('rabbito','rabbitknight','Especial','Disciplina de guarda troca alcance por resposta de perto.')]:
 edges.append(dict(**{'from':origin,'to':target},kind='configuration' if target=='rabbitknight' else 'reweaving',reason=reason,decision_status='proposed',route=route))
data=dict(family_id='rabbito',scope='Chart e concepts; nenhum gameplay, rig, save ou código alterado.',stage_mapping='II/III/IV são hipótese documental; classes existentes não comprovam espécies ou graus biológicos.',nodes=nodes,edges=edges)
(DOC/'chart.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
cards=''.join(f'<button class="card" data-id="{n["id"]}" aria-pressed="false"><img src="{n["art"] or ""}" alt="Concept {html.escape(n["name"])}"><span>{html.escape(n["name"])}</span><small>{n["route"]} · '+('configuração' if n['kind']=='configuration' else f'grau {n["stage"]} proposto')+'</small></button>' for n in nodes)
page='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rabbito — caminhos do Elo</title><style>*{box-sizing:border-box}body{margin:0;background:#102b31;color:#fcf0d4;font:17px system-ui}header,main{max-width:1440px;margin:auto;padding:32px}h1{font-size:clamp(32px,5vw,64px);margin:4px 0}p{line-height:1.65;max-width:85ch}a{color:#80ddd5}nav{display:flex;gap:24px;flex-wrap:wrap}.routes{padding:20px;border-left:4px solid #e4b548;background:#193b40;margin:24px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.card{display:flex;flex-direction:column;text-align:left;padding:12px;background:#fff9ee;border:3px solid transparent;border-radius:12px;color:#143237;cursor:pointer;font:inherit}.card img{width:100%;aspect-ratio:1;object-fit:contain}.card span{font-size:22px;font-weight:750;margin:14px 10px 6px}.card small{margin:0 10px 12px}.card[aria-pressed=true],.card:focus-visible{outline:4px solid #e4b548;outline-offset:4px}aside{padding:28px;margin-top:32px;background:#21434a;border-radius:12px;min-height:240px}dt{font-weight:700;color:#f4c96b}dd{margin:6px 0 18px;line-height:1.6}.tag{display:inline-block;border:1px solid #f4c96b;padding:6px 12px}footer{margin:36px 0}@media(max-width:800px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}main,header{padding:22px}}@media(max-width:470px){.grid{grid-template-columns:1fr}}</style><header><span class="tag">ESTUDO AUTORAL · PROPOSTAS VISUAIS</span><h1>Rabbito · caminhos do Elo</h1><p>A criação de Kael permanece singular. O amadurecimento proposto vai de escolher o próprio salto a abrir ou sustentar um caminho para outros.</p><nav><a href="CHART.md">Decisões e cânone</a><a href="PESQUISA.md">Pesquisa</a><a href="chart.json">Dados</a></nav></header><main><div class="routes"><p><b>Velocista:</b> Rabbito → Rastro dos Ventos → Arauto da Tempestade<br><b>Condutor:</b> Rabbito → Mestre dos Fios → Tecelão da Aurora<br><b>Especial:</b> Rabbito → Rabbitknight · sem sequência registrada</p><p>Os nomes vêm das classes existentes. Traduzir esses nomes em formas e graus III/IV é uma hipótese de design. Nenhuma evolução anterior à criação foi inventada.</p></div><section class="grid" aria-label="Selecionar forma">CARDS</section><aside id="details" aria-live="polite"></aside><footer>Concepts sem aprovação nova do autor. Sem recortes, rigs, animações ou integração. 45% criatura · 45% pipa · 10% pixel/2D mangá expressam direção, não certificação técnica.</footer></main><script>const data=DATA;const labels={identity:'Anatomia',story:'História proposta',action:'Verbo',mechanism:'Parte que executa a ação',tradeoff:'Limitação proposta',maturity:'Maturidade'};function select(id){const n=data.nodes.find(n=>n.id===id);document.querySelectorAll('[data-id]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.id===id));const d=document.querySelector('#details');d.replaceChildren();let h=document.createElement('h2');h.textContent=n.name;d.append(h);let s=document.createElement('p');s.textContent=n.decision_status==='approved'?'Identidade existente preservada; graus ainda propostos.':'Proposta visual · não integrada';d.append(s);let dl=document.createElement('dl');for(const [k,label]of Object.entries(labels)){if(!n[k])continue;let dt=document.createElement('dt');dt.textContent=label;let dd=document.createElement('dd');dd.textContent=n[k];dl.append(dt,dd)}d.append(dl);let a=document.createElement('a');a.href=n.brief;a.textContent='Abrir brief e incógnitas';d.append(a);location.hash=id}document.querySelectorAll('[data-id]').forEach(b=>b.addEventListener('click',()=>select(b.dataset.id)));select(data.nodes.some(n=>n.id===location.hash.slice(1))?location.hash.slice(1):'rabbito');</script></html>'''.replace('CARDS',cards).replace('DATA',json.dumps(data,ensure_ascii=False))
(DOC/'index.html').write_text(page,encoding='utf-8')
print(json.dumps({'nodes':len(nodes),'concepts':sum((ART/s[0]/'concept-v1/concept.png').exists() for s in specs),'index':str(DOC/'index.html')},ensure_ascii=False))
